+type barrierForward struct {
+	entered chan struct{}
+	release chan struct{}
+	once    sync.Once
+	count   atomic.Int64
+}
+
+func (f *barrierForward) unblock() { f.once.Do(func() { close(f.release) }) }
+
+func (f *barrierForward) Forward(_ net.Conn, _ []byte, _ string) error {
+	f.count.Add(1)
+	f.entered <- struct{}{}
