+		return err
+	}
+	var selection [2]byte
+	if _, err := io.ReadFull(conn, selection[:]); err != nil {
+		return err
+	}
+	if selection != [2]byte{0x05, 0x02} {
+		return errUpstreamRefused
+	}
+
