+
+package listener
+
+import (
+	"context"
+	"net"
+)
+
+// Serve accepts inbound connections and starts one handler per accepted
+// connection. Admission and accept-error behavior are kept identical to the
+// startup loop while that production consumer is moved behind a test seam.
+func Serve(_ context.Context, lis net.Listener, d *Deps) error {
+	for {
+		conn, err := lis.Accept()
+		if err != nil {
+			return err
+		}
+		go HandleConn(conn, d)
+	}
+}
