+func expectClientEOF(t *testing.T, h *serveHarness, c net.Conn, what string) {
+	t.Helper()
+	h.refresh(c)
+	var b [1]byte
+	if _, err := c.Read(b[:]); !errors.Is(err, io.EOF) {
+		t.Fatalf("%s close error = %v, want EOF", what, err)
+	}
+}
