+		go func(conn net.Conn) { defer func() { sendDone <- struct{}{} }(); sendValidRequest(t, h, conn) }(c)
+	}
+	for i := 0; i < forwarding; i++ {
+		h.waitSignal(t, fwd.entered, "valid request did not reach Forward")
