+// USERNAME/PASSWORD is offered; no upstream refusal can establish a tunnel.
+func socks5Connect(conn net.Conn, uname []byte, target string) error {
+	if err := writeSOCKSFrame(conn, []byte{0x05, 0x01, 0x02}); err != nil {
+		return err
+	}
