+	t.Helper()
+	budget := h.remaining()
+	if budget > 2*time.Second {
+		budget = 2 * time.Second
+	}
+	timer := time.NewTimer(budget)
+	defer timer.Stop()
+	select {
+	case <-ch:
+	case <-timer.C:
