+	case 0x01:
+		tailLen = net.IPv4len + 2
+	case 0x04:
+		tailLen = net.IPv6len + 2
+	case 0x03:
+		var nameLen [1]byte
+		if _, err := io.ReadFull(conn, nameLen[:]); err != nil {
+			return err
+		}
+		tailLen = int(nameLen[0]) + 2
+	default:
+		return errUpstreamRefused
+	}
+	var tail [255 + 2]byte
+	if tailLen > len(tail) {
+		return errUpstreamRefused
+	}
+	if _, err := io.ReadFull(conn, tail[:tailLen]); err != nil {
+		return err
+	}
+	return nil
+}
