+	clients := make([]net.Conn, plannedFramingLimit+1)
+	for i := range clients {
+		clients[i] = h.dial(l.Addr())
+	}
+	waitAccepted(t, l, plannedFramingLimit, h.deadline)
+	for i := 0; i < plannedFramingLimit; i++ {
+		h.refresh(clients[i])
+		if _, err := clients[i].Write([]byte{0x05, 0x01, 0x02}); err != nil {
