+func assertDPStandardStreamsDiscarded(t *testing.T, pid int) {
+	t.Helper()
+	if err := checkDPStandardStreams(pid, os.Readlink); err != nil {
+		t.Fatalf("data-plane stdout/stderr retention boundary: %v", err)
+	}
+}
