+	if err := writeSOCKSFrame(conn, auth); err != nil {
+		return err
+	}
+	var authReply [2]byte
+	if _, err := io.ReadFull(conn, authReply[:]); err != nil {
+		return err
+	}
+	if authReply != [2]byte{0x01, 0x00} {
+		return errUpstreamRefused
+	}
