+func TestServeReleasesPermitOnProtocolExitPaths(t *testing.T) {
+	l := listenAccepted(t)
+	verifier := &mutableVerifier{}
+	h := newServeHarness(t, l, &Deps{Auth: verifier, Forward: &stubForward{called: make(chan struct{})}, Audit: &stubAudit{}})
+	h.start()
