new file mode 100644
index 0000000..6ed8e8a
--- /dev/null
+++ b/data-plane/internal/listener/serve.go
@@ -0,0 +1,79 @@
+// Copyright 2026 The Stargate Authors
+// SPDX-License-Identifier: Apache-2.0
+
+package listener
+
+import (
+	"context"
+	"errors"
+	"net"
+	"sync"
+	"time"
+)
+
+const maxFramingHandlers = 200
+
+// Serve owns inbound admission. A permit is acquired before Accept and is
+// held only through SOCKS framing, so a stalled local client cannot create an
+// unbounded handler population and established forwarding does not consume a
+// framing slot.
+func Serve(ctx context.Context, lis net.Listener, d *Deps) error {
+	permits := make(chan struct{}, maxFramingHandlers)
+	backoff := 5 * time.Millisecond
+	const maxBackoff = time.Second
+
+	for {
+		select {
+		case <-ctx.Done():
+			return nil
+		case permits <- struct{}{}:
+		}
+
+		if ctx.Err() != nil {
+			<-permits
+			return nil
+		}
+
+		conn, err := lis.Accept()
+		if err != nil {
+			<-permits
+			if ctx.Err() != nil {
+				return nil
+			}
+			var timeoutErr interface{ Timeout() bool }
+			if errors.As(err, &timeoutErr) && timeoutErr.Timeout() {
+				timer := time.NewTimer(backoff)
+				select {
+				case <-ctx.Done():
+					timer.Stop()
+					return nil
+				case <-timer.C:
+				}
+				if backoff < maxBackoff {
+					backoff *= 2
+					if backoff > maxBackoff {
+						backoff = maxBackoff
+					}
+				}
+				continue
+			}
+			return err
+		}
+
+		if ctx.Err() != nil {
+			_ = conn.Close()
+			<-permits
+			return nil
+		}
+		backoff = 5 * time.Millisecond
+
+		var releaseOnce sync.Once
+		release := func() {
+			releaseOnce.Do(func() { <-permits })
+		}
+		go func() {
+			defer release()
+			handleConn(conn, d, release)
+		}()
+	}
+}
diff --git a/data-plane/internal/listener/serve_test.go b/data-plane/internal/listener/serve_test.go
