+func clientAuth(t *testing.T, h *serveHarness, c net.Conn, accept bool) {
+	t.Helper()
+	h.refresh(c)
+	if _, err := c.Write([]byte{0x05, 0x01, 0x02}); err != nil {
+		t.Fatalf("greeting write: %v", err)
