+	}
+	if got := audit.count(); got != forwarding {
+		t.Fatalf("auth-pass count = %d while Forward held, want %d", got, forwarding)
+	}
+	for i := 0; i < plannedFramingLimit; i++ {
+		h.dial(l.Addr())
+	}
+	waitAccepted(t, l, forwarding+plannedFramingLimit, h.deadline)
